import sqlite3
from langchain_core.tools import tool

DB_PATH = "listings.db"


@tool
def get_listing_details(mls_number: str) -> dict:
    if not mls_number or not mls_number.strip():
        return {"error": "mls_number is required"}
    mls_number = mls_number.strip().upper()
    if not mls_number.startswith("MLS-"):
        return {"error": "mls_number must start with 'MLS-'"}
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    row = conn.execute(
        "SELECT mls_number, address, city, price, bedrooms, bathrooms, sqft, status FROM listings WHERE mls_number = ?",
        (mls_number,),
    ).fetchone()
    conn.close()
    if row is None:
        return {"error": f"no listing found for {mls_number}"}
    return dict(row)

import sqlite3
from contextlib import closing
from datetime import datetime, timezone
from langchain_core.tools import tool

DB_PATH = "listings.db"


@tool
def update_listing_price(mls_number: str, new_price: float, reason: str = "") -> dict:
    if new_price <= 0:
        return {"error": "new_price must be positive"}
    mls_number = mls_number.strip().upper()
    now = datetime.now(timezone.utc).isoformat()
    with closing(sqlite3.connect(DB_PATH)) as conn:
        with conn:
            cur = conn.execute(
                "SELECT price, status FROM listings WHERE mls_number = ?",
                (mls_number,),
            )
            row = cur.fetchone()
            if row is None:
                return {"error": f"no listing found for {mls_number}"}
            old_price, status = row
            if status in ("sold", "withdrawn"):
                return {"error": f"cannot change price of a {status} listing"}
            if old_price == new_price:
                return {"mls_number": mls_number, "changed": False, "price": old_price}
            conn.execute(
                "UPDATE listings SET price = ?, updated_at = ? WHERE mls_number = ?",
                (new_price, now, mls_number),
            )
            conn.execute(
                "INSERT INTO price_history (mls_number, old_price, new_price, reason, changed_at) VALUES (?, ?, ?, ?, ?)",
                (mls_number, old_price, new_price, reason, now),
            )
    pct = round((new_price - old_price) / old_price * 100, 2)
    return {
        "mls_number": mls_number,
        "changed": True,
        "old_price": old_price,
        "new_price": new_price,
        "percent_change": pct,
    }

import os
import stripe
from agents import function_tool

stripe.api_key = os.environ["STRIPE_API_KEY"]

RATES = {"basic": 500, "premium": 1200, "spotlight": 2500}


@function_tool
def charge_listing_promotion_fee(mls_number: str, customer_id: str, days: int, tier: str = "basic") -> dict:
    if days < 1 or days > 30:
        return {"error": "days must be between 1 and 30"}
    t = tier.lower()
    if t not in RATES:
        return {"error": f"unknown tier '{tier}'"}
    if not customer_id.startswith("cus_"):
        return {"error": "invalid customer_id"}
    amt = RATES[t] * days
    if days >= 14:
        amt = int(amt * 0.9)
    key = f"promo-{mls_number}-{customer_id}-{t}-{days}"
    try:
        cust = stripe.Customer.retrieve(customer_id)
        pm = cust.get("invoice_settings", {}).get("default_payment_method")
        if not pm:
            return {"error": "customer has no default payment method"}
        pi = stripe.PaymentIntent.create(
            amount=amt,
            currency="usd",
            customer=customer_id,
            payment_method=pm,
            off_session=True,
            confirm=True,
            description=f"{t} promotion for {mls_number} ({days} days)",
            metadata={"mls_number": mls_number, "tier": t, "days": days},
            idempotency_key=key,
        )
    except stripe.error.CardError as e:
        return {"error": f"card declined: {e.user_message}"}
    except stripe.error.StripeError as e:
        return {"error": str(e)}
    return {"payment_intent": pi.id, "status": pi.status, "amount_cents": amt}

import subprocess
from dataclasses import dataclass
from agents import function_tool


@dataclass
class CompsResult:
    exit_code: int
    stdout: str
    stderr: str


@function_tool
def run_comps_report(mls_number: str, radius_miles: float = 1.0) -> CompsResult:
    cmd = ["python3", "scripts/comps_report.py", "--mls", mls_number, "--radius", str(radius_miles)]
    p = subprocess.run(cmd, capture_output=True, text=True, timeout=300)
    return CompsResult(p.returncode, p.stdout[-4000:], p.stderr[-2000:])
